"""flake8 plugin to check pep257 docstrings convention needs error code and class parser for be
included as module into flake8
"""
import io

import pep8
import pep257

__version__ = '0.2.1.post1'


class pep257Checker(object):

    """flake8 needs a class to check python file."""

    name = 'flake8-docstrings'
    version = __version__


    STDIN_NAMES = {'stdin', '-', None}

    def __init__(self, tree, filename='(none)', builtins=None):
        self.tree = tree
        self.filename = filename

    def run(self):
        """Use directly check() api from pep257."""
        source = self._get_source()
        for error in pep257.check_source(source, self.filename):
            # Ignore AllError, Environment error.
            if isinstance(error, pep257.Error):
                yield (error.line, 0, error.message, type(self))

    def _get_source(self):
        if self.filename in self.STDIN_NAMES:
            return pep8.stdin_get_value()
        with io.open(self.filename) as fd:
            return fd.read()

# -*- coding: utf-8 -*-
"""flake8 plugin to check docstring conventions with pep257.

Needs error code and class parser for be
included as module into flake8
"""
import pep8
import pep257

__version__ = '0.2.1.post1'


class pep257Checker(object):

    """Flake8 needs a class to check python file."""

    name = 'flake8-docstrings'
    version = __version__ + ', pep257:' + pep257.__version__

    STDIN = '-'
    DUMMY_FILENAME = '<stdin>'

    def __init__(self, tree, filename=None, builtins=None):
        self.tree = tree
        self.filename = filename or self.DUMMY_FILENAME
        self.source = self._get_source()

    def run(self):
        """Use check() api from pep257."""
        for error in pep257.check_source(self.source, self.filename):
            # Ignore AllError, Environment error.
            if isinstance(error, pep257.Error):
                yield (error.line, 0, error.message, type(self))

    def _get_source(self):
        if self.filename == self.STDIN:
            self.filename = self.DUMMY_FILENAME
            return pep8.stdin_get_value()
        with open(self.filename, 'r') as fp:
            return fp.read()

